-- symbol_profile: market cap + shares outstanding per symbol (source: Yahoo Finance quoteSummary API, 2026-09-14)
-- Used by gap-up-momentum strategy: exclude candidates with market_cap > 10bn EGP (validated: +16% total, all segments improved)
CREATE TABLE IF NOT EXISTS public.symbol_profile (
  symbol TEXT PRIMARY KEY,
  market_cap NUMERIC,
  shares_outstanding NUMERIC,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
GRANT SELECT ON public.symbol_profile TO anon, authenticated;

ON CONFLICT (symbol) DO UPDATE SET market_cap = EXCLUDED.market_cap, shares_outstanding = EXCLUDED.shares_outstanding, updated_at = now();